/**
 * Noctis All-Industry Specialization Registry
 *
 * Supplies deep vertical templates (24 high-demand industries), domain-written
 * seeds for all remaining Forge categories, rich SQL column mappings across
 * 50+ industry tables, and an open-domain subject synthesizer for arbitrary
 * custom prompts when running deterministically or seeding LLM synthesis.
 */

export type VisualMotif =
  | "waves"
  | "peaks"
  | "blueprint"
  | "organic"
  | "editorial"
  | "circuit"
  | "luxury"
  | "clinical";

export type SeedToolKind =
  | "booking_estimator"
  | "cart_checkout"
  | "pricing_calculator"
  | "appointment_scheduler"
  | "property_mortgage"
  | "lead_estimator";

export interface SeedShowcaseItem {
  id: string;
  title: string;
  subtitle: string;
  category: string;
  badge: string;
  metric: string;
  rating: string;
  description: string;
  features: string[];
  actionLabel: string;
}

export interface SeedSectionItem {
  icon: string;
  title: string;
  description: string;
}

export interface RichIndustryBlueprintSeed {
  industrySpecialty: string;
  parentCategorySlug: string;
  visualMotif: VisualMotif;
  brandName: string;
  domain: string;
  tagline: string;
  palette: string;
  mode: "light" | "dark";
  navLinks: [string, string, string, string, string];
  ctaLabel: string;
  eyebrow: string;
  headline: string;
  subheadline: string;
  primaryCta: string;
  secondaryCta: string;
  searchBar: {
    field1Label: string;
    field1Placeholder: string;
    field2Label: string;
    field2Options: string[];
    submitLabel: string;
  };
  stats: Array<{ value: string; label: string }>;
  showcaseTitle: string;
  showcaseSubtitle: string;
  items: SeedShowcaseItem[];
  sectionsTitle: string;
  sectionsSubtitle: string;
  sectionItems: SeedSectionItem[];
  tool: {
    kind: SeedToolKind;
    title: string;
    subtitle: string;
    unitLabel: string;
    baseRate: number;
    options: Array<{ label: string; delta: number }>;
  };
  testimonials: Array<{ quote: string; author: string; role: string }>;
  faqs: Array<{ q: string; a: string }>;
  ctaBanner: {
    headline: string;
    subheadline: string;
    buttonLabel: string;
  };
  entityNames: string[];
}

export interface SpecializedVerticalSpec extends RichIndustryBlueprintSeed {
  slug: string;
  primary: RegExp;
  secondary?: RegExp;
  boost?: number;
  needsPostGis?: boolean;
}

type CompactItemTuple = [
  title: string,
  subtitle: string,
  category: string,
  badge: string,
  metric: string,
  rating: string,
  description: string,
  features: [string, string, string],
  actionLabel: string,
];

type CompactSectionTuple = [icon: string, title: string, description: string];

function makeSeed(cfg: {
  industrySpecialty: string;
  parentCategorySlug: string;
  visualMotif: VisualMotif;
  brandName: string;
  domain: string;
  tagline: string;
  palette: string;
  mode: "light" | "dark";
  navLinks: [string, string, string, string, string];
  ctaLabel: string;
  eyebrow: string;
  headline: string;
  subheadline: string;
  primaryCta: string;
  secondaryCta: string;
  search: [string, string, string, string[], string];
  stats: Array<[string, string]>;
  showcaseTitle: string;
  showcaseSubtitle: string;
  items: CompactItemTuple[];
  sectionsTitle: string;
  sectionsSubtitle: string;
  sections: CompactSectionTuple[];
  tool: {
    kind: SeedToolKind;
    title: string;
    subtitle: string;
    unitLabel: string;
    baseRate: number;
    options: Array<[string, number]>;
  };
  testimonials: Array<[string, string, string]>;
  faqs: Array<[string, string]>;
  ctaBanner: [string, string, string];
  entityNames: string[];
}): RichIndustryBlueprintSeed {
  const prefix = cfg.parentCategorySlug.slice(0, 3);
  return {
    industrySpecialty: cfg.industrySpecialty,
    parentCategorySlug: cfg.parentCategorySlug,
    visualMotif: cfg.visualMotif,
    brandName: cfg.brandName,
    domain: cfg.domain,
    tagline: cfg.tagline,
    palette: cfg.palette,
    mode: cfg.mode,
    navLinks: cfg.navLinks,
    ctaLabel: cfg.ctaLabel,
    eyebrow: cfg.eyebrow,
    headline: cfg.headline,
    subheadline: cfg.subheadline,
    primaryCta: cfg.primaryCta,
    secondaryCta: cfg.secondaryCta,
    searchBar: {
      field1Label: cfg.search[0],
      field1Placeholder: cfg.search[1],
      field2Label: cfg.search[2],
      field2Options: cfg.search[3],
      submitLabel: cfg.search[4],
    },
    stats: cfg.stats.map(([value, label]) => ({ value, label })),
    showcaseTitle: cfg.showcaseTitle,
    showcaseSubtitle: cfg.showcaseSubtitle,
    items: cfg.items.map(([title, subtitle, category, badge, metric, rating, description, features, actionLabel], i) => ({
      id: `${prefix}-${i + 1}`,
      title,
      subtitle,
      category,
      badge,
      metric,
      rating,
      description,
      features: [...features],
      actionLabel,
    })),
    sectionsTitle: cfg.sectionsTitle,
    sectionsSubtitle: cfg.sectionsSubtitle,
    sectionItems: cfg.sections.map(([icon, title, description]) => ({ icon, title, description })),
    tool: {
      kind: cfg.tool.kind,
      title: cfg.tool.title,
      subtitle: cfg.tool.subtitle,
      unitLabel: cfg.tool.unitLabel,
      baseRate: cfg.tool.baseRate,
      options: cfg.tool.options.map(([label, delta]) => ({ label, delta })),
    },
    testimonials: cfg.testimonials.map(([quote, author, role]) => ({ quote, author, role })),
    faqs: cfg.faqs.map(([q, a]) => ({ q, a })),
    ctaBanner: {
      headline: cfg.ctaBanner[0],
      subheadline: cfg.ctaBanner[1],
      buttonLabel: cfg.ctaBanner[2],
    },
    entityNames: cfg.entityNames,
  };
}

