export function matchSpecializedVertical(prompt: string): SpecializedVerticalSpec | null {
  const hay = (prompt || "").trim().toLowerCase();
  if (!hay) return null;

  let best: SpecializedVerticalSpec | null = null;
  let bestScore = 0;

  for (const v of SPECIALIZED_VERTICALS) {
    const primaryMatches = hay.match(new RegExp(v.primary.source, "gi"))?.length ?? 0;
    const secondaryMatches = v.secondary ? hay.match(new RegExp(v.secondary.source, "gi"))?.length ?? 0 : 0;
    if (primaryMatches === 0 && secondaryMatches < 2) continue;
    const score = primaryMatches * 6 + secondaryMatches * 1.5 + (primaryMatches > 0 ? (v.boost ?? 0) : 0);
    if (score > bestScore) {
      bestScore = score;
      best = v;
    }
  }

  return best;
}

const STOP_SUBJECT_WORDS = new Set([
  "website",
  "web",
  "site",
  "webpage",
  "page",
  "landing",
  "portal",
  "platform",
  "marketplace",
  "storefront",
  "app",
  "application",
  "system",
  "modern",
  "interactive",
  "responsive",
  "complete",
  "custom",
  "build",
  "create",
  "make",
  "design",
  "develop",
  "generate",
  "draft",
  "scaffold",
  "launch",
  "full",
  "stack",
  "for",
  "the",
  "and",
  "with",
]);

function toTitleCase(text: string): string {
  return text
    .replace(/\b([a-z])([a-z0-9']*)/gi, (_, a: string, b: string) => {
      const full = (a + b).toLowerCase();
      if (["and", "or", "for", "of", "the", "in", "to", "a", "an", "by"].includes(full)) return full;
      return a.toUpperCase() + b.toLowerCase();
    })
    .replace(/^[a-z]/, (c) => c.toUpperCase())
    .replace(/\s+And\s+|\s+and\s+/g, " & ");
}

function toSafeSnakeTable(phrase: string): string | null {
  const words = phrase
    .toLowerCase()
    .replace(/[^a-z0-9\s]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter((w) => w.length > 1 && !STOP_SUBJECT_WORDS.has(w))
    .slice(0, 2);
  if (!words.length) return null;
  const joined = words.join("_");
  return /^[a-z][a-z0-9_]{2,28}$/.test(joined) ? joined : null;
}

export interface ArbitraryIndustrySynthesis {
  subject: string;
  brandName: string;
  domain: string;
  motif: VisualMotif;
  palette: string;
  mode: "light" | "dark";
  featureHints: string[];
  entityNames: string[];
}

export function extractArbitraryIndustrySubject(prompt: string): ArbitraryIndustrySynthesis | null {
  const raw = (prompt || "").trim();
  if (!raw) return null;

  // Capture trailing `with/featuring/including ...` clauses as concrete UI features + DB tables
  let featureHints: string[] = [];
  const withIdx = raw.search(/\b(?:with|featuring|including|offering)\b/i);
  const coreRaw = withIdx > 8 ? raw.slice(0, withIdx) : raw;
  if (withIdx > 8) {
    const tail = raw.slice(withIdx).replace(/^(?:with|featuring|including|offering)\s+/i, "");
    featureHints = tail
      .split(/,|;|\band\b|\+/i)
      .map((s) => s.replace(/[.!?]+$/g, "").trim())
      .filter((s) => s.length >= 4 && s.length <= 44 && !/^(?:a|an|the)$/i.test(s))
      .slice(0, 4)
      .map(toTitleCase);
  }

  let cleaned = coreRaw
    .replace(/^[•\-*\d.)\s]+/, "")
    .replace(/^(?:please\s+|can\s+you\s+|help\s+me\s+|i\s+want\s+to\s+|let'?s\s+)?/i, "")
    .replace(/^(?:build|create|make|design|develop|generate|draft|scaffold|launch)\s+(?:a|an|the)?\s*/i, "")
    .replace(/^(?:modern|interactive|responsive|complete|full[- ]?stack|custom|professional|new|sleek|beautiful|worldwide)\s+/gi, "")
    .replace(/^(?:modern|interactive|responsive|complete|full[- ]?stack|custom|professional|new|sleek|beautiful)\s+/gi, "")
    .replace(/^(?:web\s*site|website|web\s*page|webpage|landing\s*page|portal|platform|app|application)\s+(?:for|about|on|of)\s+(?:a|an|the)?\s*/i, "")
    .replace(/\s+(?:web\s*site|website|web\s*page|webpage|landing\s*page|homepage|home\s*page|web\s*app|web\s+application|platform|portal|marketplace|storefront|site|experience)\s*$/i, "")
    .replace(/\s+(?:focused|built|designed|tailored)\s+$/i, "")
    .replace(/[.!?]+$/g, "")
    .trim();

  if (!cleaned || cleaned.length < 4) return null;

  const subjectWords = cleaned
    .split(/\s+/)
    .filter((w) => w.length > 0 && !/^(?:website|webpage|portal|platform|app)$/i.test(w));
  if (subjectWords.length === 0) return null;

  const meaningless = subjectWords.every((w) => STOP_SUBJECT_WORDS.has(w.toLowerCase()));
  if (meaningless) return null;

  const subjectPhrase = subjectWords.slice(0, 7).join(" ");
  const subject = toTitleCase(subjectPhrase);

  const andIdx = subjectWords.findIndex((w) => /^(?:and|&)$/i.test(w));
  const lastWord = subjectWords[subjectWords.length - 1] || "";
  let brandWords: string[];
  if (subjectWords.length <= 4) {
    brandWords = subjectWords;
  } else if (andIdx >= 2 && andIdx <= 3) {
    const lead = subjectWords.slice(0, andIdx);
    const hasStudioNoun = /^(?:atelier|studio|lab|clinic|academy|workshop|bakery|roastery|apiary|guild|house|co)$/i.test(lead[lead.length - 1] || "");
    brandWords = hasStudioNoun || !/^(?:atelier|studio|lab|clinic|academy|workshop|bakery|roastery|apiary|guild|house|repair|exchange)$/i.test(lastWord)
      ? lead
      : [...lead, lastWord];
  } else {
    brandWords = subjectWords.filter((w) => !STOP_SUBJECT_WORDS.has(w.toLowerCase()) && w.length >= 3).slice(0, 3);
    if (!brandWords.length) brandWords = subjectWords.slice(0, 3);
  }
  const brandCore = toTitleCase(brandWords.join(" "));
  const brandName = brandCore.length > 36 ? brandCore.slice(0, 36).trim() : brandCore;
  const slugBase = brandWords.join("").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 20) || "atelier";
  const domain = `${slugBase}.com`;

  const lower = raw.toLowerCase();
  let motif: VisualMotif = "editorial";
  let palette = "ocean";
  let mode: "light" | "dark" = "dark";

  if (/\b(?:watch|horology|jewelry|diamond|luxury|atelier|tailor|antique|art\s+gallery|museum|piano|wine|ceramics)\b/i.test(lower)) {
    motif = "luxury";
    palette = "gold";
    mode = "dark";
  } else if (/\b(?:honey|bee|apiary|botanical|garden|nursery|florist|forest|herb|organic|eco|tea|coffee|ceramic)\b/i.test(lower)) {
    motif = "organic";
    palette = "emerald";
    mode = "light";
  } else if (/\b(?:robot|quantum|satellite|laser|drone|hardware|circuit|chip|sensor|lab|3d|telemetry|ai)\b/i.test(lower)) {
    motif = "circuit";
    palette = "ocean";
    mode = "dark";
  } else if (/\b(?:clinic|therapy|wellness|diagnostic|rehab|dental|optometry|counseling|nutrition|chiro)\b/i.test(lower)) {
    motif = "clinical";
    palette = "emerald";
    mode = "light";
  } else if (/\b(?:ocean|marine|diving|surf|coastal|kayak|sail|harbor|fishing)\b/i.test(lower)) {
    motif = "waves";
    palette = "ocean";
    mode = "dark";
  } else if (/\b(?:mountain|climb|ski|alpine|trail|hiking|camp|expedition)\b/i.test(lower)) {
    motif = "peaks";
    palette = "amber";
    mode = "dark";
  }

  const derivedTables = featureHints
    .map(toSafeSnakeTable)
    .filter((t): t is string => Boolean(t));
  const entities = Array.from(new Set(["services", "bookings", "inquiries", ...derivedTables])).slice(0, 5);

  return {
    subject,
    brandName,
    domain,
    motif,
    palette,
    mode,
    featureHints,
    entityNames: entities,
  };
}
